491 |     /// @notice Withdraws the sale proceeds
492 |     function withdrawProceeds() public onlyAdmin {
493 |         uint256 amount = address(this).balance;
494 |         (bool sent, ) = payable(msg.sender).call{ value: amount }("");
495 |         if (!sent) revert WithdrawalFailed();
496 |         emit ProceedsWithdrawn(msg.sender, amount);
497 |     }
