499 |     function _setReferral(string memory code, address receiver) internal {
500 |         if(referrals[code].receiver != address(0)) revert ReferralCodeInUse();
501 |         if(code.equal("")) revert InvalidCode();
502 |         string memory oldReferralCode = receiverToReferralCode[receiver];
503 |         uint256 totalClaims = 0;
504 |         if(!oldReferralCode.equal("")) {
505 |             totalClaims = referrals[receiverToReferralCode[receiver]].totalClaims;
506 |             delete referrals[receiverToReferralCode[receiver]];
507 |         }
508 |         referrals[code].receiver = receiver;
509 |         referrals[code].totalClaims = totalClaims;
510 |         receiverToReferralCode[receiver] = code;
511 |         emit ReferralUpdated(code, receiver);
512 |     }
